//! Memory Defense parity (RS-10a): the Rust redactor must reproduce
//! upstream's `apply_redaction` output on every case in the fixture
//! generated by `scripts/defense-goldens` from the vendored 1.2.1 source.

use rustsight_core::defense::{apply_redaction, pattern_count, DefenseHit};
use serde_json::Value;

#[test]
fn redaction_matches_upstream_on_every_fixture_case() {
    let raw = include_str!("fixtures/memory_defense.json");
    let fixture: Value = serde_json::from_str(raw).unwrap();
    assert_eq!(
        fixture["pattern_labels"].as_array().unwrap().len(),
        pattern_count(),
        "catalog size drifted from the vendored upstream"
    );
    let cases = fixture["cases"].as_array().unwrap();
    assert!(cases.len() > 50);
    for case in cases {
        let input = case["input"].as_str().unwrap();
        let got = apply_redaction(input);
        assert_eq!(
            got.content,
            case["content"].as_str().unwrap(),
            "content for {input:?}"
        );
        let types: Vec<String> = serde_json::from_value(case["matched_types"].clone()).unwrap();
        assert_eq!(got.matched_types, types, "matched_types for {input:?}");
        let hits: Vec<DefenseHit> = serde_json::from_value(case["hits"].clone()).unwrap();
        assert_eq!(got.hits, hits, "hits for {input:?}");
    }
}
